    out = [dict(family=f,sources=s,coverage=c,inputs=i,access=a,boundary=b,stage=p)
           for f,s,c,i,a,b,p in ROWS]
    Path(__file__).with_name('data-catalogue.json').write_text(json.dumps(out,indent=2,ensure_ascii=False)+'\n')
